class Solution:
    def solveNQueens(self, n: int) -> List[List[str]]:
        res, queens = [], []                # queens[r]：第 r 行皇后所在的列
        cols, diag1, diag2 = set(), set(), set()

        def dfs(r):
            if r == n:
                res.append(["." * c + "Q" + "." * (n - c - 1) for c in queens])
                return
            for c in range(n):
                if c in cols or r - c in diag1 or r + c in diag2:
                    continue                # 同列或同一条斜线上已经有皇后
                queens.append(c)
                cols.add(c); diag1.add(r - c); diag2.add(r + c)
                dfs(r + 1)
                queens.pop()
                cols.remove(c); diag1.remove(r - c); diag2.remove(r + c)

        dfs(0)
        return res

class Solution:
    def solveNQueens(self, n: int) -> List[List[str]]:
        def dfs(qs):
            r = len(qs)
            if r == n:
                yield ["." * c + "Q" + "." * (n - c - 1) for c in qs]
                return
            for c in range(n):
                if all(c != q and abs(c - q) != r - i for i, q in enumerate(qs)):
                    yield from dfs(qs + [c])
        return list(dfs([]))

